before.lib/worklist.ex:
defmodule Worklist do
  @moduledoc "Owns pending job IDs. The internal state is private."
  def start_link, do: Agent.start_link(fn -> %{pending: []} end)
  def add(pid, id), do: Agent.update(pid, &%{&1 | pending: [id | &1.pending]})
  def take(pid), do: Agent.get_and_update(pid, fn
    %{pending: []} = state -> {:empty, state}
    %{pending: [id | rest]} = state -> {{:ok, id}, %{state | pending: rest}}
  end)
end

